using System.Reflection;
using System.Text.Json;

namespace BerseriaAP.Game;

/// <summary>Static game data generated by BerseriaAP.DataTool (data/game_data.json, embedded).</summary>
internal sealed class GameData
{
    public sealed class Region
    {
        public string code { get; set; } = "";
        public string name { get; set; } = "";
        public int order { get; set; }
        public bool start { get; set; }
        public bool story { get; set; }
        public string? attach { get; set; }
        public bool excluded { get; set; }
    }

    public sealed class Location
    {
        public long id { get; set; }
        public string key { get; set; } = "";
        public string type { get; set; } = "";
        public string name { get; set; } = "";
        public string region { get; set; } = "";
        public long scenario { get; set; }
    }

    public sealed class Item
    {
        public long id { get; set; }
        public string name { get; set; } = "";
        public string kind { get; set; } = "";      // key | gald | game
        public string? region { get; set; }         // for keys
        public long game_id { get; set; }           // for game items
        public int count { get; set; } = 1;         // for gald
    }

    public long base_id { get; set; }
    public long goal_scenario { get; set; }
    public List<Region> regions { get; set; } = new();
    public List<Location> locations { get; set; } = new();
    public List<Item> items { get; set; } = new();

    public Dictionary<string, Location> LocationByKey { get; private set; } = new();
    public Dictionary<long, Location> LocationById { get; private set; } = new();
    public Dictionary<long, Item> ItemById { get; private set; } = new();
    public List<Location> Bosses { get; private set; } = new();

    public static GameData Load()
    {
        using var s = Assembly.GetExecutingAssembly().GetManifestResourceStream("BerseriaAP.game_data.json")
            ?? throw new InvalidOperationException("embedded game_data.json missing");
        var d = JsonSerializer.Deserialize<GameData>(s)!;
        d.LocationByKey = d.locations.ToDictionary(l => l.key);
        d.LocationById = d.locations.ToDictionary(l => l.id);
        d.ItemById = d.items.ToDictionary(i => i.id);
        d.Bosses = d.locations.Where(l => l.type == "boss").OrderBy(l => l.scenario).ToList();
        return d;
    }

    /// <summary>Region codes that have a key item (i.e. can be locked).</summary>
    public IEnumerable<string> LockableRegions => items.Where(i => i.kind == "key" && i.region != null).Select(i => i.region!);
}
